package com.hmdp.ai.infrastructure.dify;import com.fasterxml.jackson.databind.ObjectMapper;import com.hmdp.ai.domain.external.DifyWorkflowGateway;import com.hmdp.ai.domain.run.*;import com.hmdp.ai.domain.security.AuthorizationContext;import com.hmdp.ai.domain.tool.*;import org.junit.jupiter.api.Test;import java.time.Instant;import java.util.*;import static org.assertj.core.api.Assertions.assertThat;
class DifyAdapterContractTest {@Test void reportsMissingProviderWithoutDefaultOutput(){ObjectMapper mapper=new ObjectMapper();DifyWorkflowGateway gateway=(c,i,x,t)->{throw new IllegalArgumentException("DIFY_PROVIDER_NOT_CONFIGURED");};DifyToolProtocolAdapter adapter=new DifyToolProtocolAdapter(new DifyToolExecutor(gateway));ToolResult result=adapter.execute(tool(),new ToolInvocation("call","dify",1,context(),mapper.createObjectNode()),mapper.createObjectNode());assertThat(result.getErrorCode()).isEqualTo("DIFY_PROVIDER_NOT_CONFIGURED");assertThat(result.getData()).isNull();}private ToolDefinition tool(){return new ToolDefinition("t","v","dify",1,"dify",ToolProtocol.DIFY,"{}","{}",ToolRiskLevel.LOW,false,false,1000,"{}",Collections.emptyList(),"{}",true);}private ExecutionContext context(){return new ExecutionContext("t","w","u","s",null,"r","a",1,"zh","UTC",Collections.emptyList(),Collections.emptyList(),new AuthorizationContext(Collections.emptySet()),ExecutionBudget.defaults(),Instant.now().plusSeconds(10),Collections.emptyMap(),"trace");}}
